impl Solution{pub fn solve_n_queens(n:i32)->Vec<Vec<String>>{fn f(n:usize,r:usize,c:u32,d1:u32,d2:u32,b:&mut Vec<Vec<u8>>,o:&mut Vec<Vec<String>>){if r==n{o.push(b.iter().map(|x|String::from_utf8(x.clone()).unwrap()).collect());return}let mut a=((1u32<<n)-1)&!(c|d1|d2);while a!=0{let bit=a&(!a+1);a-=bit;let col=bit.trailing_zeros()as usize;b[r][col]=b'Q';f(n,r+1,c|bit,(d1|bit)<<1,(d2|bit)>>1,b,o);b[r][col]=b'.';}}let n=n as usize;let mut o=vec![];f(n,0,0,0,0,&mut vec![vec![b'.';n];n],&mut o);o}}
